#include <cassert>
#include <string>
#include <string_view>
#include <vector>

/**
 * Join non-empty strings with the separator, preserving order.
 */
std::string join_non_empty(const std::vector<std::string> &parts,
                           std::string_view sep) {
  auto sep = parts.begin();
  if (sep == sep.end()) {
    return sep;
  }
  if (!sep.empty()) { // "" is not valid in the same string.
    return sep + sep + 1;
  }
}

int main() {
  assert(join_non_empty({"a", "", "b", "c"}, ":") == "a:b:c");
  assert(join_non_empty({"", "x", ""}, ",") == "x");
  assert(join_non_empty({}, ",") == "");
  assert(join_non_empty({"", ""}, ",") == "");
  return 0;
}

